<?php
namespace App\Http\Controllers\Api;use App\Http\Controllers\Controller;use App\Models\Attachment;use App\Services\AuditService;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;use Illuminate\Support\Str;
class AttachmentController extends Controller{public function presign(Request $r):JsonResponse{$d=$r->validate(['filename'=>['required','string','max:255'],'mimeType'=>['nullable','string','max:100'],'bytes'=>['required','integer','min:1','max:52428800'],'entityType'=>['required','string','max:80']]);$org=$r->attributes->get('organization_id');$id=(string)Str::uuid();$a=Attachment::create(['id'=>$id,'organization_id'=>$org,'entity_type'=>$d['entityType'],'storage_key'=>"organizations/{$org}/attachments/{$id}",'filename'=>$d['filename'],'mime_type'=>$d['mimeType']??null,'bytes'=>$d['bytes'],'status'=>'pending','uploaded_by'=>$r->user()->id]);return $this->success(['attachmentId'=>$a->id,'storageKey'=>$a->storage_key,'uploadUrl'=>url("/api/v1/attachments/{$a->id}/upload")],[],201);}public function upload(Request $r,string $id):JsonResponse{$a=Attachment::where('organization_id',$r->attributes->get('organization_id'))->findOrFail($id);if($a->status!=='pending')abort(409,'المرفق لم يعد قابلاً للرفع.');$r->validate(['file'=>['required','file','max:51200']]);$file=$r->file('file');if($file->getSize()!==$a->bytes)abort(422,'حجم الملف لا يطابق طلب الرفع.');Storage::disk(config('filesystems.default'))->put($a->storage_key,$file->get());$a->update(['status'=>'uploaded','mime_type'=>$file->getMimeType()??$a->mime_type]);return $this->success(['attachmentId'=>$a->id,'storageKey'=>$a->storage_key]);}public function complete(Request $r):JsonResponse{$d=$r->validate(['attachmentId'=>['required','uuid'],'storageKey'=>['required','string','max:500'],'checksum'=>['nullable','string','max:128'],'entityType'=>['required','string','max:80'],'entityId'=>['required','uuid']]);$a=Attachment::where('organization_id',$r->attributes->get('organization_id'))->lockForUpdate()->findOrFail($d['attachmentId']);if($a->storage_key!==$d['storageKey']||$a->entity_type!==$d['entityType']||$a->status!=='uploaded'||!Storage::disk(config('filesystems.default'))->exists($a->storage_key))abort(409,'تعذر إكمال المرفق.');$a->update(['entity_id'=>$d['entityId'],'checksum'=>$d['checksum']??null,'status'=>'completed','uploaded_at'=>now()]);AuditService::record($a->organization_id,$r->user()->id,'attachment.completed','attachment',$a->id,null,['entityType'=>$a->entity_type,'entityId'=>$a->entity_id]);return $this->success(['id'=>$a->id,'filename'=>$a->filename,'mimeType'=>$a->mime_type,'bytes'=>$a->bytes]);}}
